'use strict';

/**
* LAPACK routine to compute the factorization of a real symmetric matrix `A` stored in packed format using the Bunch-Kaufman diagonal pivoting method.
*
* @module @stdlib/lapack/base/dsptrf
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Int32Array = require( '@stdlib/array/int32' );
* var dsptrf = require( '@stdlib/lapack/base/dsptrf' );
*
* var AP = new Float64Array( [ 4.0, 1.0, 2.0, -2.0, 0.0, 3.0, 2.0, 1.0, -2.0, -1.0 ] );
* var IPIV = new Int32Array( 4 );
*
* dsptrf( 'column-major', 'upper', 4, AP, IPIV );
* // IPIV => <Int32Array>[ 1, 2, 3, 1 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Int32Array = require( '@stdlib/array/int32' );
* var dsptrf = require( '@stdlib/lapack/base/dsptrf' );
*
* var AP = new Float64Array( [ 4.0, 1.0, 2.0, -2.0, 0.0, 3.0, 2.0, 1.0, -2.0, -1.0 ] );
* var IPIV = new Int32Array( 4 );
*
* dsptrf.ndarray( 'column-major', 'upper', 4, AP, 1, 0, IPIV, 1, 0 );
* // IPIV => <Int32Array>[ 1, 2, 3, 1 ]
*/

// MODULES //

var join = require( 'path' ).join;
var tryRequire = require( '@stdlib/utils/try-require' );
var isError = require( '@stdlib/assert/is-error' );
var main = require( './main.js' );


// MAIN //

var dsptrf;
var tmp = tryRequire( join( __dirname, './native.js' ) );
if ( isError( tmp ) ) {
	dsptrf = main;
} else {
	dsptrf = tmp;
}


// EXPORTS //

module.exports = dsptrf;

// exports: { "ndarray": "dsptrf.ndarray" }
